export class Effects {
 constructor(world){this.world=world;this.skids=[];this.particles=[];this.impacts=[];this.lightPools=[];this.flash=0;}
 lightPool(x,y,color,radius=82){this.lightPools.push({x,y,color,radius});}
 skid(x,y,angle,length=24){this.skids.push({x,y,angle,length});if(this.skids.length>600)this.skids.shift();}
 burst(x,y,n=7){for(let i=0;i<n;i++)this.particles.push({x,y,vx:this.world.rng.range(-75,75),vy:this.world.rng.range(-75,75),life:.45,size:(2+this.world.rng.next()*3)*1.5,color:'#ff9a42'});}
 impact(x,y){this.burst(x,y,15);this.flash=.06;} update(dt){const w=this.world;this.flash=Math.max(0,this.flash-dt);for(const v of w.vehicles){if(v.driver==='player'&&Math.abs(v.speed)>75&&(v._handbrake||v._hardBrake||v.damage>.4)){this.skid(v.x,v.y,v.angle);if(v._handbrake&&w.rng.chance(.28))this.particles.push({x:v.x+w.rng.range(-12,12),y:v.y+w.rng.range(-12,12),vx:w.rng.range(-18,18),vy:20,life:.75,size:7,color:'rgba(210,207,194,.55)'});}if(v.damage>.6&&w.rng.chance(.1))this.particles.push({x:v.x,y:v.y-20,vx:w.rng.range(-8,8),vy:-24,life:1.4,size:9,color:'#555753'});}for(const p of this.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;p.size+=dt*5;}this.particles=this.particles.filter(p=>p.life>0);}
 drawGround(c){for(const p of this.lightPools){const g=c.createRadialGradient(p.x,p.y,2,p.x,p.y,p.radius);g.addColorStop(0,p.color);g.addColorStop(1,'rgba(0,0,0,0)');c.fillStyle=g;c.beginPath();c.arc(p.x,p.y,p.radius,0,Math.PI*2);c.fill();}c.lineCap='round';for(const s of this.skids){c.save();c.strokeStyle=s.color||'rgba(25,25,25,.58)';c.lineWidth=s.width||1.5;if(s.curve){for(const offset of [-3,3]){c.beginPath();c.moveTo(s.curve[0][0]+offset,s.curve[0][1]);for(let i=1;i<s.curve.length;i++)c.lineTo(s.curve[i][0]+offset,s.curve[i][1]);c.stroke();}}else{c.translate(s.x,s.y);c.rotate(s.angle);c.beginPath();c.moveTo(-4,0);c.lineTo(-4,-s.length);c.moveTo(4,0);c.lineTo(4,-s.length);c.stroke();}c.restore();}}
 drawAir(c){if(this.flash>0){c.fillStyle=`rgba(255,255,255,${this.flash/.06*.48})`;const cam=this.world.camera,x=(cam?.x||640)-640,y=(cam?.y||400)-400;c.fillRect(x,y,1280,800);c.strokeStyle=`rgba(255,255,255,${this.flash/.06*.42})`;c.lineWidth=32;c.strokeRect(x+16,y+16,1248,768);}for(const p of this.particles){c.globalAlpha=Math.max(0,Math.min(.24,p.life*.19));c.fillStyle=p.color;if(this.world._marinaShotMarker){c.beginPath();c.moveTo(p.x,p.y-p.size);c.lineTo(p.x+p.size*.55,p.y-p.size*.3);c.lineTo(p.x+p.size,p.y);c.lineTo(p.x+p.size*.3,p.y+p.size*.45);c.lineTo(p.x,p.y+p.size);c.lineTo(p.x-p.size*.45,p.y+p.size*.3);c.lineTo(p.x-p.size,p.y);c.lineTo(p.x-p.size*.3,p.y-p.size*.55);c.closePath();c.fill();}else{c.beginPath();c.arc(p.x,p.y,p.size,0,Math.PI*2);c.fill();}}c.globalAlpha=1;for(const p of this.impacts){c.save();c.lineCap='square';c.strokeStyle='#fff4c9';c.lineWidth=2;c.beginPath();c.moveTo(p.x-7,p.y);c.lineTo(p.x-2,p.y-2);c.lineTo(p.x,p.y-7);c.lineTo(p.x+2,p.y-2);c.lineTo(p.x+7,p.y);c.lineTo(p.x+2,p.y+2);c.lineTo(p.x,p.y+7);c.lineTo(p.x-2,p.y+2);c.closePath();c.stroke();c.strokeStyle='#ff9a42';c.lineWidth=1;c.beginPath();c.moveTo(p.x-5,p.y+4);c.lineTo(p.x-9,p.y+7);c.moveTo(p.x+4,p.y-4);c.lineTo(p.x+8,p.y-7);c.stroke();c.restore();}}
}
